/// Branch every brain repo serves and the exporter commits to.
pub const BRAIN_BRANCH: &str = "main";

/// Path of the exporter-owned manifest inside the vault tree.
pub const MANIFEST_PATH: &str = ".kyma/manifest.json";

/// `provenance.source` value on memory nodes ingested from a brain push.
pub const BRAIN_PROVENANCE_SOURCE: &str = "brain-repo";

/// Prefix of the deterministic upsert key for notes born from a push:
/// `brain:<brain-name>:<rel-path>`.
pub const TOPIC_KEY_PREFIX: &str = "brain:";

/// Prefix of the topic key that routes a memory into `wiki/`:
/// `wiki:<brain-name>:<page-slug>`.
pub const WIKI_TOPIC_PREFIX: &str = "wiki:";

/// Build the upsert key for a push-born note.
pub fn topic_key(brain: &str, rel_path: &str) -> String {
    format!("{TOPIC_KEY_PREFIX}{brain}:{rel_path}")
}

/// Errors surfaced by the brain core.
#[derive(Debug, thiserror::Error)]
pub enum BrainError {
    #[error("git binary unavailable")]
    GitUnavailable,
    #[error("git {op} failed: {detail}")]
    Git { op: &'static str, detail: String },
    #[error("invalid brain name: {0}")]
    InvalidName(String),
    #[error("invalid vault path: {0}")]
    InvalidPath(String),
    #[error("io: {0}")]
    Io(#[from] std::io::Error),
    #[error("serde: {0}")]
    Serde(#[from] serde_json::Error),
    #[error("{0}")]
    Other(String),
}

/// Validate a brain name (also the repo directory stem): lowercase
/// alphanumeric plus `-`/`_`, 1–64 chars, must start alphanumeric.
pub fn validate_name(name: &str) -> Result<(), BrainError> {
    let ok = !name.is_empty()
        && name.len() <= 64
        && name.chars().next().is_some_and(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
        && name
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-' || c == '_');
    if ok {
        Ok(())
    } else {
        Err(BrainError::InvalidName(name.to_string()))
    }
}
